export const MODEL_B2: number[] = [0.014602926288845648, -0.036819101957226597, 0.1820933260061634, -0.17711201336983107, 0.1224396550128102, -0.13666231304102397, -0.15336410944974552, -0.3002259856349269, -0.2306117029514527, -0.03648838836077182, -0.27711404436428416, 0.27472233685547964, -0.12012715099534746, -0.17945245006202168, -0.15102883083833876, -0.016351215651399704, -0.26360917061522154, 0.11487369033985281, 0.2609267516069543, -0.1547243238354527, -0.015308129367686326, -0.14026125172172782, 0.15840354444069607, -0.07228047885337945, -0.1252726545493014, -0.2585922451752791, -0.012112893918661922, -0.02681215102539058, -0.13821135718916286, 0.15718464162311463, 0.04644748206235841, 0.18953619378770395, -0.2009987306968012, 0.19609106012341246, 0.15464075635129312, -0.28733249591411264, 0.18562819146163434, -0.05371841951533493];

export function predictFestivalOrNumber(features: number[]): { predictedClass: string; confidence: number } | null {
  if (!features || features.length !== 79) return null;
  
  // Layer 1
  const h1 = new Array(MODEL_B0.length);
  for (let j = 0; j < MODEL_B0.length; j++) {
    let sum = MODEL_B0[j] || 0;
    for (let i = 0; i < features.length; i++) {
      sum += (features[i] || 0) * (MODEL_W0[i]?.[j] || 0);
    }
    h1[j] = Math.max(0, sum);
  }

  // Layer 2
  const h2 = new Array(MODEL_B1.length);
  for (let j = 0; j < MODEL_B1.length; j++) {
    let sum = MODEL_B1[j] || 0;
    for (let i = 0; i < h1.length; i++) {
      sum += (h1[i] || 0) * (MODEL_W1[i]?.[j] || 0);
    }
    h2[j] = Math.max(0, sum);
  }

  // Output Layer
  const logits = new Array(MODEL_B2.length);
  let maxLogit = -Infinity;
  for (let j = 0; j < MODEL_B2.length; j++) {
    let sum = MODEL_B2[j] || 0;
    for (let i = 0; i < h2.length; i++) {
      sum += (h2[i] || 0) * (MODEL_W2[i]?.[j] || 0);
    }
    logits[j] = sum;
    if (sum > maxLogit) maxLogit = sum;
  }

  let expSum = 0;
  const probs = new Array(logits.length);
  for (let j = 0; j < logits.length; j++) {
    probs[j] = Math.exp(logits[j] - maxLogit);
    expSum += probs[j];
  }

  let bestIdx = 0;
  let bestProb = 0;
  for (let j = 0; j < probs.length; j++) {
    const prob = expSum > 0 ? probs[j] / expSum : 0;
    if (prob > bestProb) {
      bestProb = prob;
      bestIdx = j;
    }
  }

  return {
    predictedClass: FESTIVAL_AND_NUMBER_CLASSES[bestIdx] || "Unknown",
    confidence: bestProb
  };
}
